package agent

default allow = false

# Allow transactions up to $50
allow {
  input.action == "purchase"
  input.amount <= 50.0
}

# Allow cart modifications without amount limit
allow {
  input.action == "add_to_cart"
}

package agent
default allow = false
# Allow during business hours allow { input.action == "submit_order" time.clock(time.now_ns())[0] >= 9 time.clock(time.now_ns())[0] < 18 }

package agent

default allow = false

# Premium users can access all features
allow {
  input.user.tier == "premium"
}

# Standard users limited to basic actions
allow {
  input.user.tier == "standard"
  input.action == "read"
}
